func TestConcurrentAccess(t *testing.T) {
	clk := newFakeClock()
	l, _ := New(1000, 100, clk)
	var wg sync.WaitGroup
	var allowed int64
	var mu sync.Mutex
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 10; j++ {
				if l.Allow() {
					mu.Lock()
					allowed++
					mu.Unlock()
				}
			}
		}()
	}
	wg.Wait()
	if allowed > 100 {
		t.Fatalf("allowed = %d, must not exceed burst 100", allowed)
	}
}
